import json


def diff(a, b):
    ops = []
    _walk(a, b, "$", ops)
    return sorted(ops)


def _is_container(v):
    return isinstance(v, (dict, list))


def _same_container(x, y):
    return (isinstance(x, dict) and isinstance(y, dict)) or (isinstance(x, list) and isinstance(y, list))


def _equal(x, y):
    if type(x) is not type(y):
        return False
    return x == y


def _walk(x, y, path, ops):
    if _same_container(x, y):
        if isinstance(x, dict):
            for key in x:
                child = path + "." + key  # hmm — key might not be str? In JSON always str. Use str(key)? The spec says "adds `.key`". Assume str.
                if key in y:
                    _walk(x[key], y[key], child, ops)
                else:
                    ops.append("- {}: {}".format(child, json.dumps(x[key], sort_keys=True)))
            for key in y:
                if key not in x:
                    ops.append("+ {}: {}".format(path + "." + key, json.dumps(y[key], sort_keys=True)))
        else:
            n = min(len(x), len(y))
            for i in range(n):
                _walk(x[i], y[i], path + "[" + str(i) + "]", ops)
            for i in range(n, len(x)):
                ops.append("- {}[{}]: {}".format(path, i, json.dumps(x[i], sort_keys=True)))
            for i in range(n, len(y)):
                ops.append("+ {}[{}]: {}".format(path, i, json.dumps(y[i], sort_keys=True)))
    elif not _equal(x, y):
        ops.append("~ {}: {} -> {}".format(path, json.dumps(x, sort_keys=True), json.dumps(y, sort_keys=True)))
```

